svg.script:
(function(){
  var s=document.querySelectorAll('.s'), st=document.querySelectorAll('.step'), hint=document.getElementById('hint'), cur=0, user=false, timer=0;
  function show(i){ cur=(i+s.length)%s.length;
    for(var k=0;k<s.length;k++){ s[k].setAttribute('opacity',k===cur?1:0);
      var r=st[k].querySelector('rect'), c=st[k].querySelector('circle'), n=st[k].querySelectorAll('text')[0];
      r.setAttribute('fill-opacity',k===cur?1:0); c.setAttribute('fill',k===cur?'#E5097F':'#fff'); n.setAttribute('fill',k===cur?'#fff':'#E5097F'); } }
  function take(){ if(!user){ user=true; clearInterval(timer); hint.setAttribute('opacity',0); } }
  document.getElementById('screen').addEventListener('click',function(){ take(); show(cur+1); });
  for(var k=0;k<st.length;k++){ (function(i){ st[i].addEventListener('click',function(){ take(); show(i); }); })(k); }
  document.documentElement.addEventListener('keydown',function(e){ if(e.key==='ArrowRight'||e.key==='ArrowDown'){take();show(cur+1);e.preventDefault();} if(e.key==='ArrowLeft'||e.key==='ArrowUp'){take();show(cur-1);e.preventDefault();} });
  var started=false;
  function demo(){ if(started||user) return; started=true; hint.setAttribute('opacity',1); timer=setInterval(function(){ if(!user) show(cur+1); },3200); }
  try{ new IntersectionObserver(function(es){ if(es[0].isIntersecting&&es[0].intersectionRatio>.5) demo(); },{threshold:[.5]}).observe(document.documentElement); }catch(_){ setTimeout(demo,600); }
  show(0);
})();
